V = "ProHance"
CS = "Vendor case study"
LG = "Vendor testimonial/logo"
CSB = "https://www.prohance.ai/case-study/"
TM = "https://www.prohance.ai/testimonials.php"
DATE_NOTE = "ProHance case-study sitemap gives one bulk lastmod (2025-05-14) for every story, so the original publication date is unknown; the testimonials page is live in 2026."
BIG = "10k+ employee enterprise — low Tavilo priority."
def cs(name, slug, summary, industry="", country="", domain="", emp="", empsrc="", contacts=None, li="", phone="", email="", csrc="",
       status="PROBABLE", conf=75, pitch="", notes="", second="", signals=""):
    return dict(company_name=name, company_domain=domain, industry=industry, hq_country=country, employee_count=emp, employee_count_source_url=empsrc,
        vendor=V, evidence_type=CS, evidence_summary=summary, source_url=CSB+slug, source_publication_date="",
        second_source_url=second, status=status, status_reason="Live named ProHance case study, date unknown (sitemap lastmod 2025-05)",
        confidence_score=conf, contacts=contacts or [], company_linkedin=li, company_phone=phone, public_email=email,
        contact_source_url=csrc, pitch_angle=pitch, workforce_signals=signals, notes=(notes+" "+DATE_NOTE).strip())
def tm(name, who, title, industry="", country="", domain="", contacts_extra=None, li="", phone="", email="", csrc="", notes="", conf=75, pitch="", signals=""):
    c=[{"name":who,"title":title,"linkedin":"","source_url":TM}] + (contacts_extra or [])
    return dict(company_name=name, company_domain=domain, industry=industry, hq_country=country, vendor=V, evidence_type=LG,
        evidence_summary=f"Named testimonial on ProHance's live 'Discover how leading brands drive impact' page from {who} ({title}) praising ProHance for productivity / work-time visibility.",
        source_url=TM, source_publication_date="2026", status="PROBABLE", status_reason="Named customer testimonial on live vendor page (2026); quote date unknown",
        confidence_score=conf, contacts=c, company_linkedin=li, company_phone=phone, public_email=email, contact_source_url=csrc,
        pitch_angle=pitch, workforce_signals=signals, notes=notes)
